/**
 * Exact storage probes (bounded zero proofs and COMPLETE stored-term enumerations) are facts about committed data.
 * Their caches must be keyed on the store's data revision, not on the sketch synopsis identity that only moves when a
 * background rebuild publishes, and they must be dropped by {@link LmdbFilterSelectivityStats#reset()}.
 */
class LmdbExactProbeCacheDataRevisionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final ValueFactory REPOSITORY_VF = SimpleValueFactory.getInstance();
	private static final SketchSnapshotIdentity SNAPSHOT = new SketchSnapshotIdentity(11L, 29L, 7L);
	private static final IRI P = REPOSITORY_VF.createIRI("urn:p");
	private static final IRI A = REPOSITORY_VF.createIRI("urn:a");
	private static final IRI B = REPOSITORY_VF.createIRI("urn:b");
	private static final IRI C = REPOSITORY_VF.createIRI("urn:c");

	@Test
	void dataRevisionInvalidatesExactZeroProbe(@TempDir Path dataDir) throws Exception {
		AtomicLong dataRevision = new AtomicLong(3L);
		ProbeFixture fixture = fixture(dataDir, () -> SNAPSHOT, dataRevision, row(1L, 2L, 3L));
		Filter filter = filter("subject", "value", "keep");

		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		dataRevision.incrementAndGet();
		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));

		verify(fixture.tripleStore, times(4)).getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(),
				anyLong(), anyBoolean());
	}

	@Test
	void dataRevisionInvalidatesFiniteSupportProbe(@TempDir Path dataDir) throws Exception {
		AtomicLong dataRevision = new AtomicLong(3L);
		ProbeFixture fixture = fixture(dataDir, () -> SNAPSHOT, dataRevision, row(1L, 2L, 3L), row(5L, 2L, 4L));
		Filter filter = filter("subject", "value", "keep");

		LmdbFilterSelectivityStats.DistinctFilterValues first = fixture.stats.exactMatchingDistinctValues(
				pattern(filter), filter.getCondition(), "value", 4_096);
		fixture.stats.exactMatchingDistinctValues(pattern(filter), filter.getCondition(), "value", 4_096);
		dataRevision.incrementAndGet();
		LmdbFilterSelectivityStats.DistinctFilterValues reprobed = fixture.stats.exactMatchingDistinctValues(
				pattern(filter), filter.getCondition(), "value", 4_096);

		assertEquals(LmdbFilterSelectivityStats.DistinctFilterStatus.COMPLETE, first.status());
		assertEquals(List.of(VF.createLiteral("keep")), reprobed.matchingValues());
		// one enumeration scans the explicit and the inferred surface: two probes (first + re-probe) = four scans
		verify(fixture.tripleStore, times(4)).getTriplesWithDistinctCursorSkip(any(Txn.class),
				any(StatementPattern.class), anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean(),
				any(LmdbValueIdFilter.class));
	}

	@Test
	void sketchIdentityChangeAloneDoesNotClearProbes(@TempDir Path dataDir) throws Exception {
		AtomicReference<SketchSnapshotIdentity> snapshot = new AtomicReference<>(SNAPSHOT);
		AtomicLong dataRevision = new AtomicLong(3L);
		ProbeFixture fixture = fixture(dataDir, snapshot::get, dataRevision, row(1L, 2L, 3L));
		Filter filter = filter("subject", "value", "keep");

		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		snapshot.set(new SketchSnapshotIdentity(11L, 29L, 8L));
		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));

		verify(fixture.tripleStore, times(2)).getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(),
				anyLong(), anyBoolean());
	}

	@Test
	void resetClearsExactProbeCaches(@TempDir Path dataDir) throws Exception {
		AtomicLong dataRevision = new AtomicLong(3L);
		// only the rejected row, so the bounded zero probe is conclusive (ALL_REJECTED) and the stored-term
		// enumeration is COMPLETE with no matching value; both results are cacheable
		ProbeFixture fixture = fixture(dataDir, () -> SNAPSHOT, dataRevision, row(1L, 2L, 3L));
		Filter filter = filter("subject", "value", "keep");

		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		LmdbFilterSelectivityStats.DistinctFilterValues first = fixture.stats.exactMatchingDistinctValues(
				pattern(filter), filter.getCondition(), "value", 4_096);
		assertEquals(LmdbFilterSelectivityStats.DistinctFilterStatus.COMPLETE, first.status());
		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		fixture.stats.exactMatchingDistinctValues(pattern(filter), filter.getCondition(), "value", 4_096);
		verify(fixture.tripleStore, times(2)).getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(),
				anyLong(), anyBoolean());
		verify(fixture.tripleStore, times(2)).getTriplesWithDistinctCursorSkip(any(Txn.class),
				any(StatementPattern.class), anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean(),
				any(LmdbValueIdFilter.class));

		fixture.stats.reset();
		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		fixture.stats.exactMatchingDistinctValues(pattern(filter), filter.getCondition(), "value", 4_096);

		// every probe scans the explicit and the inferred surface; reset() must have forced both re-probes
		verify(fixture.tripleStore, times(4)).getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(),
				anyLong(), anyBoolean());
		verify(fixture.tripleStore, times(4)).getTriplesWithDistinctCursorSkip(any(Txn.class),
				any(StatementPattern.class), anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean(),
				any(LmdbValueIdFilter.class));
	}

	@Test
	void sketchKeyedExactProbeCacheMustNotServeStaleTermSetAfterCommit(@TempDir File dataDir) {
		assertExactProbeCacheFresh(dataDir, new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true), true);
	}

	@Test
	void defaultExactProbeCacheMustNotServeStaleTermSetAfterCommit(@TempDir File dataDir) {
		assertExactProbeCacheFresh(dataDir, new LmdbStoreConfig("spoc,posc"), false);
	}

	private static void assertExactProbeCacheFresh(File dataDir, LmdbStoreConfig config, boolean sketch) {
		String first = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 5) }";
		String second = "SELECT ?o ?s WHERE { ?s <urn:p> ?o FILTER(?o = 5) }";
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, config));
		repository.init();
		LmdbStore store = (LmdbStore) repository.getSail();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, REPOSITORY_VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, REPOSITORY_VF.createLiteral("6", XSD.INTEGER));
			if (sketch) {
				store.getBackingStore().getSketchBasedJoinEstimator().stop();
				store.getBackingStore().getSketchBasedJoinEstimator().rebuild();
			}
			store.rebuildFrontierStatistics();
			assertEquals(Set.of("urn:a"), rows(connection, first, "s"));

			connection.add(C, P, REPOSITORY_VF.createLiteral("5", XSD.INT));
			Set<String> secondRows = rows(connection, second, "s");

			assertEquals(Set.of("urn:a", "urn:c"), secondRows,
					"a fresh query shape must not reuse a pre-commit COMPLETE stored-term set (sketch=" + sketch
							+ ")");
		} finally {
			repository.shutDown();
		}
	}

	private static ProbeFixture fixture(Path dataDir, java.util.function.Supplier<SketchSnapshotIdentity> identity,
			AtomicLong dataRevision, long[]... explicitRows) throws Exception {
		ValueStore valueStore = mock(ValueStore.class);
		TripleStore tripleStore = mock(TripleStore.class);
		TxnManager txnManager = mock(TxnManager.class);
		Txn txn = mock(Txn.class);
		when(tripleStore.getTxnManager()).thenReturn(txnManager);
		when(tripleStore.getDataRevision()).thenAnswer(invocation -> dataRevision.get());
		when(txnManager.createReadTxn()).thenReturn(txn);
		// planner-time probes read through the (pinned or ordinary) planning transaction
		when(tripleStore.planningReadTxn()).thenReturn(txn);
		when(valueStore.getId(any(Value.class))).thenReturn(2L);
		when(valueStore.getValue(1L)).thenReturn(new LmdbIRI(null, "urn:test:subject:first", 1L));
		when(valueStore.getValue(2L)).thenReturn(new LmdbIRI(null, "urn:test:predicate", 2L));
		when(valueStore.getValue(3L)).thenReturn(new LmdbLiteral(null, "drop", 3L));
		when(valueStore.getValue(4L)).thenReturn(new LmdbLiteral(null, "keep", 4L));
		when(valueStore.getValue(5L)).thenReturn(new LmdbIRI(null, "urn:test:subject:second", 5L));
		when(tripleStore.getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean()))
				.thenAnswer(invocation -> invocation.getArgument(5, Boolean.class)
						? rows(explicitRows)
						: rows());
		when(tripleStore.distinctCursorSkipPlan(any(StatementPattern.class)))
				.thenReturn(Optional.of(new LmdbDistinctCursorSkipSupport.Plan("posc", 2, 0, 0)));
		when(tripleStore.getTriplesWithDistinctCursorSkip(any(Txn.class), any(StatementPattern.class), anyLong(),
				anyLong(), anyLong(), anyLong(), anyBoolean(), any(LmdbValueIdFilter.class)))
						.thenAnswer(invocation -> Optional.of(invocation.getArgument(6, Boolean.class)
								? rows(explicitRows)
								: rows()));
		LmdbFilterSelectivityStats stats = new LmdbFilterSelectivityStats(
				dataDir.resolve("join-estimator.rjes"), tripleStore, valueStore, false, 0L, 0, false,
				identity, 0, () -> false);
		return new ProbeFixture(stats, tripleStore);
	}

	private static long[] row(long subject, long predicate, long object) {
		return new long[] { subject, predicate, object, 0L };
	}

	private static RecordIterator rows(long[]... rows) {
		AtomicInteger index = new AtomicInteger();
		return new RecordIterator() {
			@Override
			public long[] next() {
				int next = index.getAndIncrement();
				return next < rows.length ? rows[next] : null;
			}

			@Override
			public void close() {
				// Nothing to release in the in-memory test cursor.
			}
		};
	}

	private static Filter filter(String subjectName, String objectName, String expected) {
		String query = "SELECT * WHERE { ?" + subjectName + " <urn:test:predicate> ?" + objectName
				+ " . FILTER(?" + objectName + " = \"" + expected + "\") }";
		Filter[] found = new Filter[1];
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null)
				.getTupleExpr()
				.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Filter node) {
						if (found[0] == null) {
							found[0] = node;
						}
						super.meet(node);
					}
				});
		return found[0];
	}

	private static StatementPattern pattern(Filter filter) {
		return (StatementPattern) filter.getArg();
	}

	private static Set<String> rows(RepositoryConnection connection, String query, String... names) {
		Set<String> rows = new TreeSet<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			for (BindingSet bindingSet : result) {
				StringBuilder row = new StringBuilder();
				for (int index = 0; index < names.length; index++) {
					if (index > 0) {
						row.append('|');
					}
					row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
							: bindingSet.getValue(names[index]).stringValue());
				}
				rows.add(row.toString());
			}
		}
		return rows;
	}

	private record ProbeFixture(LmdbFilterSelectivityStats stats, TripleStore tripleStore) {
	}
}
